import { ErrorBoundary } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { SwitchCase } from '@toss/react';
import { Suspense, useState } from 'react';
import { EmptyList } from '~/widgets/empty-list';
import { CommonErrorFallback } from '~/widgets/fallbacks/common-error-fallback';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { WalletHistoryDetailParams } from '~/entities/wallet/api/use-wallet-history-detail-query';
import { isValidationError } from '~/entities/wallet/lib/errors';
import { useWalletHistoryDetail, useWalletParams } from '~/entities/wallet/lib/use-wallet-history-detail';
import { DetailContainer } from '~/entities/wallet/ui/wallet-history-detail/detail-container';
import { CashbackTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/cashback';
import { ConversionTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/conversion';
import { PaymentTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/payment';
import { RefundTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/refund';
import { RemittanceTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/remittance';
import { SwitchDepositTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/switch-deposit';
import { TopUpTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/top-up';
import { TransferDepositTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/transfer-deposit';
import { VouchTemplate } from '~/entities/wallet/ui/wallet-history-detail/templates/vouch';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

type ErrorFallbackProps = {
  error: Error;
  reset: () => void;
};

export const Content = ({
  params,
  skipValidation,
}: {
  params: WalletHistoryDetailParams;
  skipValidation?: boolean;
}) => {
  const { detailData } = useWalletHistoryDetail(params, { skipValidation });

  if (!detailData || !detailData.trnscTypeCd) {
    return <EmptyList message={i18n.t('validation:noHistoryAvailable')} />;
  }

  return (
    <DetailContainer>
      <SwitchCase
        value={detailData.trnscTypeCd}
        caseBy={{
          [TrnscTypeCd.송금]: <RemittanceTemplate data={detailData} />,
          [TrnscTypeCd.환불송금]: <RemittanceTemplate data={detailData} />,
          [TrnscTypeCd.예금전환]: <SwitchDepositTemplate data={detailData} />,
          [TrnscTypeCd.전환입금]: <TransferDepositTemplate data={detailData} />,
          [TrnscTypeCd.전환]: <ConversionTemplate data={detailData} />,
          [TrnscTypeCd.충전]: <TopUpTemplate data={detailData} />,
          [TrnscTypeCd.캐시백]: <CashbackTemplate data={detailData} />,
          [TrnscTypeCd.캐시백환불]: <CashbackTemplate data={detailData} />,
          [TrnscTypeCd.보조금]: <VouchTemplate data={detailData} />,
          [TrnscTypeCd.보조금환불]: <VouchTemplate data={detailData} />,
          [TrnscTypeCd.결제]: <PaymentTemplate data={detailData} />,
          [TrnscTypeCd.온라인결제]: <PaymentTemplate data={detailData} />,
          [TrnscTypeCd.환불]: <RefundTemplate data={detailData} />,
        }}
      />
    </DetailContainer>
  );
};

export const WalletHistoryDetailPage = () => {
  useSetHeaderTitle(i18n.t('usageHistory'));
  const params = useWalletParams();
  const [skipValidation, setSkipValidation] = useState(false);

  return (
    <QueryErrorResetBoundary>
      {({ reset }) => (
        <ErrorBoundary
          shouldCatch={(error) => isValidationError(error)}
          resetKeys={[params.tbAcnutMastr.trnscId]}
          fallback={(props: ErrorFallbackProps) => {
            const handleConfirmClick = async () => {
              setSkipValidation(true);
              reset();
              props.reset();
            };

            return (
              <CommonErrorFallback
                error={props.error}
                resetErrorBoundary={reset}
                onConfirmClick={handleConfirmClick}
                buttonLabel={[i18n.t('confirm')]}
              />
            );
          }}
        >
          <Suspense
            fallback={
              <div className="empty">
                <LoadingSpinner />
              </div>
            }
          >
            <Content key={params.tbAcnutMastr.trnscId} params={params} skipValidation={skipValidation} />
          </Suspense>
        </ErrorBoundary>
      )}
    </QueryErrorResetBoundary>
  );
};
