import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { IssueReceiptResponseStatus } from '~/shared/api/dtos/enums';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { resultify } from '~/shared/lib/utils/resultify';

export const useCheckReceiptStatusMutation = (options?: MutationOptions<any, CBDCAxiosError, any>) => {
  const { openAlertDialog } = useAlertDialog();
  const checkReceiptStatus = (trnscId: string) => {
    //임시 parameter
    return resultify(
      axios.post<any>(`${API_URLS.receipt(`/issue/result?trnscId=${trnscId}`)}`).catch<any>((error) => {
        let res = {};
        if (error.response?.data?.status === '400' && error.response?.data?.message.includes('발급 이력'))
          res = {
            response_status: IssueReceiptResponseStatus.미발급,
          };
        return res;
      }),
    );
  };

  const mutation = useMutation<any, CBDCAxiosError, any>({
    ...options,
    mutationFn: (trnscId: string) => checkReceiptStatus(trnscId),
  });

  return {
    ...mutation,
  };
};
