import { Fragment } from 'react/jsx-runtime';
import { RefundSttus } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

type DetailTopProps = {
  coinTypeNm?: string;
  reqWalletInsttNm?: string;
  reqWalletInsttCd?: string;
  trnscTypeCdNm?: string;
  title?: string;
  refundSttus?: RefundSttus | null;
};

export const DetailTop = ({ coinTypeNm, reqWalletInsttNm, reqWalletInsttCd, title, trnscTypeCdNm }: DetailTopProps) => {
  return (
    <Fragment>
      <div className="detail-top">
        {trnscTypeCdNm && (
          <div className={`detail-type ${trnscTypeCdNm.includes('환불') ? 'repay' : 'trn'}`}>{trnscTypeCdNm}</div>
        )}

        <div className="wallet-asset-info">
          <span className="type">{coinTypeNm || i18n.t('depositToken')}</span>|
          <span className={`wallet-account ${reqWalletInsttCd}`}>{reqWalletInsttNm}</span>
        </div>
      </div>
      {title && <div className="detail-memo">{title}</div>}
    </Fragment>
  );
};
