import { useErrorBoundary } from '@suspensive/react';
import { z } from 'zod';
import { useCodeValueName } from '~/entities/comcode/lib/use-code-value-name';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { useVoucherLists } from '~/entities/voucher/lib/use-voucher-lists';
import { DetailAmountItem } from '~/entities/wallet/ui/wallet-history-detail/detail-amount-item';
import { DetailDateItem } from '~/entities/wallet/ui/wallet-history-detail/detail-date-item';
import { DetailPaymentInfo } from '~/entities/wallet/ui/wallet-history-detail/detail-payment-info';
import { DetailTop } from '~/entities/wallet/ui/wallet-history-detail/detail-top';
import { RcppaySttusCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useVoucherNavigation } from '~/shared/lib/hooks/use-navigate';
import { WalletHistoryDetailTemplateProps } from '.';

const voucherNavigationSchema = z.object({
  vouchId: z.string(),
  vouchData: z.object({}).passthrough(),
});

export const CashbackTemplate = ({ data }: WalletHistoryDetailTemplateProps) => {
  const { navigateToVoucherDetail } = useVoucherNavigation();
  const { findVoucherById } = useVoucherLists();
  const { setError } = useErrorBoundary();
  const { codeName } = useCodeValueName(COM_CODE.TRANSACTION_TYPE, data.trnscTypeCd ?? '');

  const handleVoucherInfoClick = async () => {
    try {
      const vouchData = await findVoucherById(data.vouchId ?? '');
      const validatedVoucher = voucherNavigationSchema.parse({
        vouchId: data.vouchId,
        vouchData,
      });

      navigateToVoucherDetail(validatedVoucher.vouchId, validatedVoucher.vouchData);
    } catch (error) {
      setError(error as Error);
    }
  };

  return (
    <div className="has-btm-btn flex flex-auto flex-col">
      <div className="detail-area">
        <div className="detail-box">
          <DetailTop
            coinTypeNm={data.coinTypeNm ?? ''}
            reqWalletInsttNm={data.reqWalletInsttNm ?? ''}
            reqWalletInsttCd={data.reqWalletInsttCd ?? ''}
            title={data.title ?? ''}
            trnscTypeCdNm={codeName ?? ''}
          />
          <div className="detail-info">
            <ul>
              <DetailAmountItem
                label={i18n.t('cashbackAmount')}
                amount={Number(data.cashbagAmt)}
                rcppaySttusCd={data.rcppaySttusCd as RcppaySttusCd}
                reqWalletInsttNm={data.reqWalletInsttNm || ''}
                myAliasNm={data.myAliasNm || ''}
              />
              <DetailDateItem label={i18n.t('dateTime')} date={data.trnscDcsnDt ?? ''} />
              <li className="vouc-info">
                <span>{i18n.t('voucherInfo')}</span>
                <button type="button" className="vouc-info-btn" onClick={handleVoucherInfoClick}>
                  {data.vouchNm ?? ''}
                </button>
              </li>
            </ul>
          </div>
        </div>
      </div>
      <DetailPaymentInfo
        walletDpstr={data.walletDpstr ?? ''}
        amt={Number(data.amt)}
        trnscDcsnDt={data.trnscDcsnDt ?? ''}
        keyId={data.keyId ?? ''}
      />
    </div>
  );
};
