import { SwitchCase } from '@toss/react';
import { RefundDialog } from '~/entities/wallet/ui/wallet-history-detail/refund-dialog';
import { RefundSttus } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';
import { RefundNotice } from './refund-notice';

type RefundStatusButtonsProps = {
  refundSttus: string;
  isOnlinePayment: boolean;
  refundId?: string | null;
  trnscId?: string | null;
};

export const RefundStatusButtons = ({ refundSttus, isOnlinePayment, trnscId, refundId }: RefundStatusButtonsProps) => {
  const { navigate } = useNavigate();

  const handleClickRefund = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog afterLeave={unmount} open={isOpen} onClose={close} buttonLabel={[]}>
          <RefundDialog />
        </Dialog>
      );
    });
  };

  const handleClickRefundReceipt = () => {
    navigate(`${PATHS.myWallet.history}/${refundId}?trnscId=${trnscId}`);
  };

  return (
    <SwitchCase
      value={refundSttus ?? ''}
      caseBy={{
        [RefundSttus.환불가능]: (
          <>
            <RefundNotice isOnlinePayment={isOnlinePayment} />
            <div className="btn-area">
              {!isOnlinePayment && (
                <button className="btm-btn app" onClick={handleClickRefund}>
                  {i18n.t('refund')}
                </button>
              )}
            </div>
          </>
        ),
        [RefundSttus.환불실패]: (
          <>
            <RefundNotice isOnlinePayment={isOnlinePayment} />
            <div className="btn-area">
              {!isOnlinePayment && (
                <button className="btm-btn app" onClick={handleClickRefund}>
                  {i18n.t('refund')}
                </button>
              )}
            </div>
          </>
        ),
        [RefundSttus.환불요청]: (
          <>
            <RefundNotice isOnlinePayment={isOnlinePayment} />
            <div className="btn-area">
              {!isOnlinePayment && (
                <button className="btm-btn app" onClick={handleClickRefund}>
                  {i18n.t('refund')}
                </button>
              )}
            </div>
          </>
        ),
        [RefundSttus.환불완료]: (
          <div className="btn-area">
            <button className="btm-btn app" onClick={handleClickRefundReceipt}>
              {i18n.t('viewRefundReceipt')}
            </button>
          </div>
        ),
        [RefundSttus.환불처리중]: (
          <>
            <RefundNotice isOnlinePayment={isOnlinePayment} />
            <div className="btn-area">
              <button className="btm-btn disabled" disabled>
                {i18n.t('refundWaiting')}
              </button>
            </div>
          </>
        ),
      }}
    />
  );
};
