import i18n from '~/shared/i18n/i18n';

type DetailRefundApprovalProps = {
  refundCd: string | null;
};

export const DetailRefundApproval = ({ refundCd }: DetailRefundApprovalProps) => {
  if (!refundCd) return null;

  return (
    <li>
      <span className="shrink-0">{i18n.t('refundApprovalNumber')}</span>
      <p className="text-wrap break-all pl-5">{refundCd}</p>
    </li>
  );
};
