import clsx from 'clsx';
import { isEmpty } from 'lodash-es';
import { useEffect, useState } from 'react';
import { useCodeValueName } from '~/entities/comcode/lib/use-code-value-name';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { useCancelReceiptMutation } from '~/entities/exchange/api/hooks/use-cancel-receipt-mutation';
import { useCheckCanIssueReceiptMutation } from '~/entities/exchange/api/hooks/use-check-can-issue-receipt-mutation';
import { useCheckReceiptStatusMutation } from '~/entities/exchange/api/hooks/use-check-receipt-status-mutation';
import { useExchangeNavigation } from '~/entities/exchange/lib/use-exchange-navigation';
import { TokenItem, UserResponse } from '~/entities/pin/api/dtos/schemas';
import { findTokenItemById } from '~/entities/user';
import { getUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { DEFAULT_TOKEN_ID } from '~/entities/user/lib/transform-user-with-token-list';
import { useUpdateDefaultWalletMutation } from '~/entities/wallet/api/use-update-default-wallet-mutation';
import { DetailAmountItem } from '~/entities/wallet/ui/wallet-history-detail/detail-amount-item';
import { DetailDateItem } from '~/entities/wallet/ui/wallet-history-detail/detail-date-item';
import { DetailTop } from '~/entities/wallet/ui/wallet-history-detail/detail-top';
import { ReceiptDialog } from '~/entities/wallet/ui/wallet-history-detail/receipt-dialog';
import { RcppaySttusCd, TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { overlay } from '~/shared/lib/overlay';
import { PATHS, PathType } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';
import { WalletHistoryDetailTemplateProps } from '.';

type ClickProps = {
  trnscTypeCd: TrnscTypeCd;
  path: PathType;
  param: any;
};

export const RemittanceTemplate = ({ data }: WalletHistoryDetailTemplateProps) => {
  const userRes = getUserRes() as UserResponse;
  const { codeName } = useCodeValueName(COM_CODE.TRANSACTION_TYPE, data.trnscTypeCd ?? '');
  const isReceived = data.rcppaySttusCd === RcppaySttusCd.입금코드 && data.trnscTypeCd === TrnscTypeCd.송금;
  const isSent = data.rcppaySttusCd === RcppaySttusCd.출금코드 && data.trnscTypeCd === TrnscTypeCd.송금;
  const hasBizNo = !isEmpty(userRes.tbCstmrMastr.ewaBizNo);
  const isRefunded = !isEmpty(data.refundTransferId);

  //const isOnlinePayment = data.trnscTypeCd === TrnscTypeCd.;
  const amountLabel = isReceived ? i18n.t('receivedAmount') : i18n.t('transferAmount');
  const [canIssueReceipt, setCanIssueReceipt] = useState<boolean>(false);
  const { mutateAsync: checkReceiptStatus } = useCheckReceiptStatusMutation();
  const { mutateAsync: fnCanIssueReceipt } = useCheckCanIssueReceiptMutation();
  const { mutateAsync: cancelReceipt } = useCancelReceiptMutation();
  const { mutateAsync: updateDefaultWallet } = useUpdateDefaultWalletMutation();

  const item: TokenItem = findTokenItemById(userRes.tbCstmrMastr.tokenList, DEFAULT_TOKEN_ID);
  const { openAlertDialog } = useAlertDialog();

  const { navigateToExchange } = useExchangeNavigation();

  const trnscAmt = data.trnscAmt?.toString() || '0';

  //송금(받기) => 환불하기 클릭 시 송금 화면으로 이동
  const handleClick =
    ({ trnscTypeCd, path, param }: ClickProps) =>
    async () => {
      if (!data.myAliasNm) return;
      await updateDefaultWallet(data.myAliasNm); //환불송금할 사업자지갑을 기본 지갑으로 설정

      navigateToExchange({
        path,
        item,
        trnscTypeCd,
        param,
        trnscAmt,
      });
      //현금영수증취소 추가 필요
      //await cancelReceipt(cstmrNo)
    };

  const handleClickIssue = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={() => checkIssueReceiptStatus()}
          open={isOpen}
          onClose={close}
          buttonLabel={[]}
          layerIndex={30}
        >
          <ReceiptDialog />
        </Dialog>
      );
    });
  };

  const checkIssueReceiptStatus = async () => {
    const res = await fnCanIssueReceipt(data.trnscId);
    if (isEmpty(res)) {
      setCanIssueReceipt(true);
      return;
    }
    setCanIssueReceipt(false);
  };

  useEffect(() => {
    //현금영수증 발행 가능한건인지 check
    if (hasBizNo && isReceived && !isRefunded) {
      checkIssueReceiptStatus();
    }
  }, []);

  return (
    <div className="has-btm-btn bottom-fixed flex flex-auto flex-col">
      <div className="detail-area">
        <div className="detail-box">
          <DetailTop
            coinTypeNm={data.coinTypeNm ?? ''}
            reqWalletInsttNm={data.reqWalletInsttNm ?? ''}
            reqWalletInsttCd={data.reqWalletInsttCd ?? ''}
            title={data.title ?? ''}
            trnscTypeCdNm={codeName ?? ''}
          />
          <div className="detail-info">
            <ul>
              <DetailAmountItem
                label={amountLabel}
                amount={data.trnscAmt ?? 0}
                rcppaySttusCd={data.rcppaySttusCd as RcppaySttusCd}
                reqWalletInsttNm={data.reqWalletInsttNm || ''}
                myAliasNm={data.myAliasNm || ''}
              />
              <DetailDateItem label={i18n.t('dateTime')} date={data.trnscDcsnDt ?? ''} />
              {!isEmpty(data.ntsApprovalCd) && (
                <li>
                  <span>{i18n.t('rcptApprovalCd')}</span>
                  <p>{data.ntsApprovalCd}</p>
                </li>
              )}
              {isSent && (
                <li>
                  <span>{i18n.t('transferWallet')}</span>
                  <p>
                    {data.resWalletInsttNm} {data.aliasNm}
                  </p>
                </li>
              )}
            </ul>
          </div>
        </div>
      </div>
      {hasBizNo && isReceived && !isRefunded && (
        <div className={'btm-btn-area confirm half'}>
          <button
            onClick={() => {
              //환불하기
              if (!canIssueReceipt) {
                //현금영수증 발급 이력이 있는 송금건의 경우 환불 시 현금영수증이 취소된다는 alert 표출
                openAlertDialog({
                  message: i18n.t('validation:refundReceiptConfirmation'),
                  buttonLabel: ['취소', '확인'],
                  onConfirmClick: handleClick({
                    trnscTypeCd: TrnscTypeCd.송금,
                    path: PATHS.exchange.root,
                    param: { isRefund: true, issuedReceipt: !canIssueReceipt, historyId: data.trnscId },
                  }),
                  onCancelClick: () => {
                    // 취소 시 아무 작업 없음
                  },
                });
              } else {
                //현금영수증 발급 이력이 없는 경우 바로 송금화면으로 이동
                navigateToExchange({
                  path: PATHS.exchange.root,
                  item,
                  trnscTypeCd: TrnscTypeCd.송금,
                  param: { isRefund: true, issuedReceipt: !canIssueReceipt, historyId: data.trnscId },
                  trnscAmt,
                });
              }
            }}
            type="button"
            className={clsx('btm-btn')}
            id="charge"
          >
            {i18n.t('refund')}
          </button>
          <button
            onClick={() => handleClickIssue()} //현금영수증 발행
            type="button"
            className={clsx('btm-btn app', { disabled: !canIssueReceipt })}
            id="charge"
            disabled={!canIssueReceipt}
          >
            {i18n.t('receipt')}
          </button>
        </div>
      )}
    </div>
  );
};
