import { useErrorBoundary } from '@suspensive/react';
import { useEffect, useState } from 'react';
import { z } from 'zod';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { useVoucherLists } from '~/entities/voucher/lib/use-voucher-lists';
import { WalletHistoryDetailData } from '~/entities/wallet/api/dtos/wallet-history-detail';
import { RcppaySttusCd, VoucherType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useVoucherNavigation } from '~/shared/lib/hooks';

type paymentVouchProps = {
  data: WalletHistoryDetailData;
};

const voucherNavigationSchema = z.object({
  vouchId: z.string(),
  vouchData: z.object({}).passthrough(),
});
type vouchSchema = z.infer<typeof voucherNavigationSchema>;

export const DetailPaymentVouchInfo = ({ data }: paymentVouchProps) => {
  const [voucherNavData, setVoucherNavData] = useState<vouchSchema>({ vouchId: '', vouchData: {} });
  const [voucherData, setVoucherData] = useState<VoucherItemDTO>({});
  const { navigateToVoucherDetail } = useVoucherNavigation();
  const { findVoucherById, isLoading } = useVoucherLists();
  const { setError } = useErrorBoundary();

  const readVouchList = async () => {
    if (!data?.vouchId) {
      return;
    }

    try {
      const vouchData = await findVoucherById(data.vouchId ?? '');
      const validatedVoucher = await voucherNavigationSchema.parse({
        vouchId: data.vouchId,
        vouchData,
      });

      setVoucherNavData(validatedVoucher);
      setVoucherData(validatedVoucher.vouchData || {});
    } catch (error) {
      setError(error as Error);
    }
  };

  const handleVouchAmtClick = async () => {
    if (!voucherNavData?.vouchId) return false;
    await navigateToVoucherDetail(voucherNavData.vouchId, { ...voucherNavData.vouchData, type: VoucherType.내_바우처 });
  };

  useEffect(() => {
    if (isLoading) return;
    readVouchList();
  }, [isLoading, data?.vouchId]);

  return (
    <ul>
      <li>
        <div className="vouch-info-detail">
          <div>
            <span>
              {data.vouchNm} {data.vouchTypeNm}
            </span>
          </div>
          <div className="vouch-info-detail-amt">
            <span>
              {data.rcppaySttusCd === RcppaySttusCd.출금코드 ? i18n.t('use') : i18n.t('useCancel')}
              {i18n.t('generalAmount')}
            </span>
            <span>
              {Number(data.vouchAmt).toLocaleString()}
              {i18n.t('won')}
            </span>
          </div>
        </div>
      </li>
      <div className={`vouc-box`}>
        <div className="vouc-balance">
          <p style={{ fontSize: 'var(--font-size-15)', fontWeight: '400' }}>{i18n.t('nowHoldingBalance')}</p>
          <p style={{ fontSize: 'var(--font-size-15)', fontWeight: '400' }} onClick={() => handleVouchAmtClick()}>
            {voucherData?.pbmBalanceOf?.toLocaleString() || '0'}
            {i18n.t('won')}
          </p>
        </div>
      </div>
    </ul>
  );
};
