import { useCodeValueName } from '~/entities/comcode/lib/use-code-value-name';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { getUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { DetailDateItem } from '~/entities/wallet/ui/wallet-history-detail/detail-date-item';
import { DetailPaymentVouchInfo } from '~/entities/wallet/ui/wallet-history-detail/detail-payment-vouch-info';
import { DetailRefundApproval } from '~/entities/wallet/ui/wallet-history-detail/detail-refund-approval';
import { DetailTop } from '~/entities/wallet/ui/wallet-history-detail/detail-top';
import { DetailVouchAmountItem } from '~/entities/wallet/ui/wallet-history-detail/detail-vouch-amount-item';
import { RcppaySttusCd, RefundSttus, TrnscTypeCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS, PathType } from '~/shared/routes/paths';
import { WalletHistoryDetailTemplateProps } from '.';

type ClickProps = {
  trnscTypeCd: TrnscTypeCd;
  path: PathType;
  param: any;
};

export const VouchTemplate = ({ data }: WalletHistoryDetailTemplateProps) => {
  const userRes = getUserRes() as UserResponse;
  const { navigate } = useNavigate();
  const { codeName } = useCodeValueName(COM_CODE.TRANSACTION_TYPE, data.trnscTypeCd ?? '');
  const { shortBankName } = useComBankInfo(data.fromInsttCd);

  const amountLabel = data.rcppaySttusCd === RcppaySttusCd.출금코드 ? i18n.t('paymentAmount') : i18n.t('refundAmount');

  //console.log(data.refundSttus === RefundSttus.환불완료 && data.refundCd);

  const handleClickRefundedTransactions = () => {
    navigate(`${PATHS.myWallet.historyDetail}${data.trnscId}`);
  };

  return (
    <div className="has-btm-btn bottom-fixed flex flex-auto flex-col">
      <div className="detail-area">
        <div className="detail-box">
          <DetailTop //거래타입 표출 부분 (ex.결제, 송금, 보조금, 환불 등)
            coinTypeNm={i18n.t('subsidy') ?? ''}
            reqWalletInsttNm={data.reqWalletInsttNm ?? ''}
            reqWalletInsttCd={data.reqWalletInsttCd ?? ''}
            title={data.vouchNm ?? ''}
            trnscTypeCdNm={codeName ?? ''}
          />
          <div className="detail-info">
            <ul>
              <DetailVouchAmountItem
                label={amountLabel}
                amount={data.trnscAmt ?? 0}
                rcppaySttusCd={data.rcppaySttusCd as RcppaySttusCd}
                detailData={data}
              />
              <DetailDateItem label={i18n.t('dateTime')} date={data.trnscDcsnDt ?? ''} />
              <li>
                <span>{i18n.t('merchantInfo')}</span>
                <p>{data.title}</p>
              </li>
              {data.refundSttus === RefundSttus.환불완료 && data.refundCd && (
                <DetailRefundApproval refundCd={data.refundCd} />
              )}
            </ul>
          </div>
        </div>
      </div>
      {data.vouchId && (
        <div className="detail-btm-info">
          <div className="pay-info-top">
            <h3>{i18n.t('benefits')}</h3>
          </div>
          <div className="pay-info-detail">
            <DetailPaymentVouchInfo data={data} />
          </div>
        </div>
      )}
      {/* <RefundStatusButtons
        refundSttus={data.refundSttus ?? ''}
        isOnlinePayment={isOnlinePayment}
        refundId={data.refundId ?? ''}
        trnscId={data.trnscId ?? ''}
      /> */}
      {data.trnscId && data.refundSttus === RefundSttus.환불완료 && data.refundCd && (
        <div className="btn-area" onClick={handleClickRefundedTransactions}>
          <button className="btm-btn app">{i18n.t('viewRefundedTransactions')}</button>
        </div>
      )}
    </div>
  );
};
